package com.shahabsystem.livewebwallpaper;
import android.content.*;
public final class Prefs { private Prefs(){} private static SharedPreferences p(Context c){return c.getSharedPreferences("p",0);} public static int mode(Context c){return p(c).getInt("mode",1);} public static int speed(Context c){return p(c).getInt("speed",55);} public static int codeSpeed(Context c){return p(c).getInt("codeSpeed",55);} public static int bg(Context c){return p(c).getInt("bg",0xFF050607);} public static int accent(Context c){return p(c).getInt("accent",0xFFFF6A00);} public static int dim(Context c){return p(c).getInt("dim",0);} public static float zoom(Context c){return p(c).getFloat("zoom",1f);} public static String url(Context c){return p(c).getString("url","https://example.com");} public static boolean hideScroll(Context c){return p(c).getBoolean("hideScroll",true);} public static boolean full(Context c){return p(c).getBoolean("full",true);} public static void save(Context c,int m,int s,int cs,int bg,int a,int d,float z,String u,boolean hs,boolean f){p(c).edit().putInt("mode",m).putInt("speed",s).putInt("codeSpeed",cs).putInt("bg",bg).putInt("accent",a).putInt("dim",d).putFloat("zoom",z).putString("url",u).putBoolean("hideScroll",hs).putBoolean("full",f).apply();}}
